package ir.laxipatem.lexiflash.ui

import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * WCAG contrast checks for the fixed brand palette.
 *
 * Only the hand-picked colours are tested. Material You dynamic palettes are
 * generated by the system, which guarantees its own contrast, so they are out of
 * scope here.
 *
 * The colours are declared again as plain 24-bit integers instead of importing
 * Compose's `Color`, so this test runs on a bare JVM with no Android or Compose
 * classes on the classpath. If a colour in `Color.kt` changes, this file must be
 * updated with it, which is exactly the review moment the check is meant to
 * create.
 */
class ContrastTest {

    private object Palette {
        const val PRIMARY = 0xA85C10
        const val PRIMARY_CONTAINER_LIGHT = 0xFBEAD2
        const val PRIMARY_CONTAINER_DARK = 0x4A2A05
        const val ACCENT = 0xA8503C
        const val ACCENT_INK = 0x8A3B29
        const val ACCENT_CONTAINER_LIGHT = 0xFAE3DC
        const val ACCENT_CONTAINER_DARK = 0x4A1F16
        const val BACKGROUND_LIGHT = 0xF4E4CB
        const val SURFACE_LIGHT = 0xFFFBF5
        const val SURFACE_RAISED_LIGHT = 0xFFF3E0
        const val SURFACE_EDGE_LIGHT = 0xEDD7B5
        const val INK_LIGHT = 0x3B2A1A
        const val MUTED_LIGHT = 0x6E5A47
        const val BACKGROUND_DARK = 0x1A1310
        const val SURFACE_DARK = 0x251B15
        const val INK_DARK = 0xF2E6D8
        const val MUTED_DARK = 0xBDA893
        const val ERROR_LIGHT = 0xB3261E
        const val ERROR_DARK = 0xF2B8B5
        const val ON_ERROR_LIGHT = 0xFFFFFF
        const val ON_ERROR_DARK = 0x601410
        const val SUCCESS_LIGHT = 0x1B6E3C
        const val SUCCESS_DARK = 0x7ED6A1
        const val RAISED_DARK = 0x3A2A1D
    }

    private fun channel(value: Int): Double {
        val normalized = value / 255.0
        return if (normalized <= 0.03928) {
            normalized / 12.92
        } else {
            ((normalized + 0.055) / 1.055).pow(2.4)
        }
    }

    private fun luminance(rgb: Int): Double {
        val red = (rgb shr 16) and 0xFF
        val green = (rgb shr 8) and 0xFF
        val blue = rgb and 0xFF
        return 0.2126 * channel(red) + 0.7152 * channel(green) + 0.0722 * channel(blue)
    }

    /** WCAG contrast ratio, always ≥ 1. */
    private fun contrast(first: Int, second: Int): Double {
        val a = luminance(first)
        val b = luminance(second)
        return (max(a, b) + 0.05) / (min(a, b) + 0.05)
    }

    private fun assertAA(label: String, first: Int, second: Int, minimum: Double = 4.5) {
        val ratio = contrast(first, second)
        assertTrue(
            "$label has contrast %.2f, needs %.1f".format(ratio, minimum),
            ratio >= minimum
        )
    }

    @Test
    fun `body text on the light background passes AA`() {
        assertAA("ink on background", Palette.INK_LIGHT, Palette.BACKGROUND_LIGHT)
        assertAA("ink on surface", Palette.INK_LIGHT, Palette.SURFACE_LIGHT)
    }

    @Test
    fun `secondary text on the light background passes AA`() {
        assertAA("muted on background", Palette.MUTED_LIGHT, Palette.BACKGROUND_LIGHT)
        assertAA("muted on surface", Palette.MUTED_LIGHT, Palette.SURFACE_LIGHT)
    }

    @Test
    fun `body text on the dark background passes AA`() {
        assertAA("ink on background", Palette.INK_DARK, Palette.BACKGROUND_DARK)
        assertAA("ink on surface", Palette.INK_DARK, Palette.SURFACE_DARK)
    }

    @Test
    fun `secondary text on the dark background passes AA`() {
        assertAA("muted on background", Palette.MUTED_DARK, Palette.BACKGROUND_DARK)
        assertAA("muted on surface", Palette.MUTED_DARK, Palette.SURFACE_DARK)
    }

    @Test
    fun `white on the primary brand colour passes AA`() {
        // 5.0:1 for the warmed amber; a brighter one failed at 4.09:1.
        assertAA("white on primary", 0xFFFFFF, Palette.PRIMARY)
    }

    /** The lit top face of a raised primary button still carries its label. */
    @Test
    fun `the raised primary variants carry white text`() {
        assertAA("white on the top face", 0xFFFFFF, Palette.PRIMARY)
        assertAA("white on the bottom edge", 0xFFFFFF, 0x8A4A08)
    }

    @Test
    fun `ink on the primary container passes AA`() {
        assertAA("ink on primary container", Palette.INK_LIGHT, Palette.PRIMARY_CONTAINER_LIGHT)
        assertAA(
            "light ink on dark primary container",
            0xDCE7F7,
            Palette.PRIMARY_CONTAINER_DARK
        )
    }

    @Test
    fun `ink on the accent container passes AA`() {
        assertAA("ink on accent container", Palette.INK_LIGHT, Palette.ACCENT_CONTAINER_LIGHT)
        assertAA(
            "light ink on dark accent container",
            0xFBEBC4,
            Palette.ACCENT_CONTAINER_DARK
        )
    }

    @Test
    fun `error colours pass AA`() {
        assertAA("on-error on error (light)", Palette.ON_ERROR_LIGHT, Palette.ERROR_LIGHT)
        assertAA("on-error on error (dark)", Palette.ON_ERROR_DARK, Palette.ERROR_DARK)
        assertAA("error text on light surface", Palette.ERROR_LIGHT, Palette.SURFACE_LIGHT)
    }

    @Test
    fun `success colours pass AA`() {
        assertAA("success on light surface", Palette.SUCCESS_LIGHT, Palette.SURFACE_LIGHT)
        assertAA("success on dark surface", Palette.SUCCESS_DARK, Palette.SURFACE_DARK)
    }

    /**
     * A raised card is a face on a page with an edge peeking out below it. If the
     * face and the page were the same luminance the card would vanish, so this
     * pins the difference at the WCAG non-text threshold.
     */
    @Test
    fun `a raised card separates from the page it sits on`() {
        assertAA(
            "raised face on the page",
            Palette.SURFACE_RAISED_LIGHT,
            Palette.BACKGROUND_LIGHT,
            1.10
        )
        assertAA(
            "raised face on the dark page",
            Palette.RAISED_DARK,
            Palette.BACKGROUND_DARK,
            1.20
        )
    }

    @Test
    fun `large text and icons only need three to one`() {
        // Headlines are ≥24pt and decorative icons are exempt from the 4.5 rule.
        assertAA("primary on light surface", Palette.PRIMARY, Palette.SURFACE_LIGHT, 3.0)
        assertAA("accent on light surface", Palette.ACCENT, Palette.SURFACE_LIGHT, 3.0)
    }

    @Test
    fun `accent coloured text passes AA`() {
        // The amber accent is a highlight colour, so text uses the darker variant.
        assertAA("accent ink on light surface", Palette.ACCENT_INK, Palette.SURFACE_LIGHT)
        assertAA("accent ink on light background", Palette.ACCENT_INK, Palette.BACKGROUND_LIGHT)
    }

    @Test
    fun `the contrast formula behaves like the specification`() {
        // Sanity-check the maths against two known values.
        assertTrue("black on white must be 21:1", kotlin.math.abs(contrast(0x000000, 0xFFFFFF) - 21.0) < 0.01)
        assertTrue("white on white must be 1:1", kotlin.math.abs(contrast(0xFFFFFF, 0xFFFFFF) - 1.0) < 0.001)
    }
}
